function appendEventLog(log: { offset: number; payload: string; timestamp: number }[], payload: string, timestamp: number): { offset: number; payload: string; timestamp: number } {
  const record = { offset: log.length, payload, timestamp };
  log.push(record);
  return record;
}

stream-web-assign-day-1:
function findFirstOffsetAtOrAfter(log: { offset: number; timestamp: number }[], targetTimestamp: number): number | null {
  let low = 0;
  let high = log.length - 1;
  let ans: number | null = null;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (log[mid].timestamp >= targetTimestamp) {
      ans = log[mid].offset;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  return ans;
}

stream-web-exam-day-2:
function hashKeyToPartition(key: string, partitionCount: number): number {
  if (partitionCount <= 0) return 0;
  let hash = 5381;
  for (let i = 0; i < key.length; i++) {
    hash = ((hash << 5) + hash) + key.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash) % partitionCount;
}

stream-web-assign-day-2:
function createStickyRoundRobinPartitioner(partitionCount: number, batchSizeLimit: number): (key: string | null) => number {
  let currentPartition = 0;
  let currentBatchCount = 0;
  return (key: string | null): number => {
    if (partitionCount <= 0) return 0;
    if (key !== null) {
      return key.length % partitionCount;
    }
    const assigned = currentPartition;
    currentBatchCount++;
    if (currentBatchCount >= batchSizeLimit) {
      currentPartition = (currentPartition + 1) % partitionCount;
      currentBatchCount = 0;
    }
    return assigned;
  };
}

stream-web-exam-day-3:
function pollPartitionRecords(records: { offset: number; payload: string }[], currentOffset: number, maxRecords: number, highWaterMark: number): { records: { offset: number; payload: string }[]; nextOffset: number } {
  const eligible = records.filter(r => r.offset >= currentOffset && r.offset < highWaterMark);
  const sliced = eligible.slice(0, Math.max(0, maxRecords));
  const nextOffset = sliced.length > 0 ? sliced[sliced.length - 1].offset + 1 : currentOffset;
  return { records: sliced, nextOffset };
}

stream-web-assign-day-3:
function computeConsumerLag(hwms: Record<number, number>, committed: Record<number, number>): { totalLag: number; perPartitionLag: Record<number, number>; maxLagPartition: number; maxLag: number } {
  const perPartitionLag: Record<number, number> = {};
  let totalLag = 0;
  let maxLag = -1;
  let maxLagPartition = -1;
  for (const partStr of Object.keys(hwms)) {
    const part = Number(partStr);
    const hwm = hwms[part] || 0;
    const comm = committed[part] !== undefined ? committed[part] : 0;
    const lag = Math.max(0, hwm - comm);
    perPartitionLag[part] = lag;
    totalLag += lag;
    if (lag > maxLag) {
      maxLag = lag;
      maxLagPartition = part;
    }
  }
  return { totalLag, perPartitionLag, maxLagPartition, maxLag: Math.max(0, maxLag) };
}

stream-web-exam-day-4:
function validatePartitionSequences(events: { partition: number; offset: number; sequence: number }[]): { valid: boolean; violations: { partition: number; expected: number; actual: number }[] } {
  const lastSeq: Record<number, number> = {};
  const violations: { partition: number; expected: number; actual: number }[] = [];
  for (const e of events) {
    if (lastSeq[e.partition] !== undefined) {
      if (e.sequence <= lastSeq[e.partition]) {
        violations.push({ partition: e.partition, expected: lastSeq[e.partition] + 1, actual: e.sequence });
      }
    }
    lastSeq[e.partition] = e.sequence;
  }
  return { valid: violations.length === 0, violations };
}

stream-web-assign-day-4:
function mergeTimestampedPartitions(partitions: { partition: number; timestamp: number; payload: string }[][]): { partition: number; timestamp: number; payload: string }[] {
  const flat: { partition: number; timestamp: number; payload: string }[] = [];
  for (const part of partitions) {
    for (const item of part) flat.push(item);
  }
  return flat.sort((a, b) => {
    if (a.timestamp !== b.timestamp) return a.timestamp - b.timestamp;
    return a.partition - b.partition;
  });
}

stream-web-exam-day-5:
class InMemoryEventBroker {
  private partitions: { offset: number; key: string; payload: string }[][] = [];
  constructor(public numPartitions: number) {
    for (let i = 0; i < numPartitions; i++) {
      this.partitions.push([]);
    }
  }
  produce(key: string, payload: string): { partition: number; offset: number } {
    const part = key.length % this.numPartitions;
    const offset = this.partitions[part].length;
    this.partitions[part].push({ offset, key, payload });
    return { partition: part, offset };
  }
  consume(partition: number, startOffset: number, maxCount: number): { offset: number; key: string; payload: string }[] {
    if (partition < 0 || partition >= this.numPartitions) return [];
    const log = this.partitions[partition];
    return log.filter(r => r.offset >= startOffset).slice(0, maxCount);
  }
  getHighWaterMark(partition: number): number {
    if (partition < 0 || partition >= this.numPartitions) return 0;
    return this.partitions[partition].length;
  }
}

