class ConsumerHeartbeatTracker {
  private lastHeartbeat = new Map<string, number>();
  constructor(public sessionTimeoutMs: number) {}
  heartbeat(consumerId: string, timestampMs: number): void {
    this.lastHeartbeat.set(consumerId, timestampMs);
  }
  getDeadMembers(currentTimestampMs: number): string[] {
    const dead: string[] = [];
    for (const [id, ts] of this.lastHeartbeat.entries()) {
      if (currentTimestampMs - ts > this.sessionTimeoutMs) {
        dead.push(id);
      }
    }
    return dead.sort();
  }
}

stream-web-exam-day-8:
class BatchOffsetTracker {
  private pending = new Map<number, number>();
  recordProcessed(partition: number, offset: number): void {
    const current = this.pending.get(partition);
    const next = offset + 1;
    if (current === undefined || next > current) {
      this.pending.set(partition, next);
    }
  }
  getPendingCommits(): Record<number, number> {
    const res: Record<number, number> = {};
    for (const [p, o] of this.pending.entries()) {
      res[p] = o;
    }
    return res;
  }
  commit(): Record<number, number> {
    const res = this.getPendingCommits();
    this.pending.clear();
    return res;
  }
}

stream-web-assign-day-8:
function computeCommitRetryDelay(attempt: number, baseDelayMs: number, maxDelayMs: number, backoffFactor: number = 2): number {
  if (attempt < 0) return 0;
  const raw = baseDelayMs * Math.pow(backoffFactor, attempt);
  return Math.min(maxDelayMs, Math.round(raw));
}

stream-web-exam-day-9:
function evaluateDeliveryOutcome(strategy: 'at-most-once' | 'at-least-once', crashDuringProcessing: boolean): { dataLossPossible: boolean; duplicatesPossible: boolean; offsetCommitted: boolean; messageProcessed: boolean } {
  if (strategy === 'at-most-once') {
    if (crashDuringProcessing) {
      return { dataLossPossible: true, duplicatesPossible: false, offsetCommitted: true, messageProcessed: false };
    }
    return { dataLossPossible: false, duplicatesPossible: false, offsetCommitted: true, messageProcessed: true };
  } else {
    if (crashDuringProcessing) {
      return { dataLossPossible: false, duplicatesPossible: true, offsetCommitted: false, messageProcessed: false };
    }
    return { dataLossPossible: false, duplicatesPossible: false, offsetCommitted: true, messageProcessed: true };
  }
}

stream-web-assign-day-9:
class DeduplicationWindowFilter {
  private seen = new Set<string>();
  private order: string[] = [];
  constructor(public windowCapacity: number) {}
  checkAndMark(messageId: string): boolean {
    if (this.seen.has(messageId)) {
      return true;
    }
    if (this.order.length >= this.windowCapacity) {
      const oldest = this.order.shift()!;
      this.seen.delete(oldest);
    }
    this.seen.add(messageId);
    this.order.push(messageId);
    return false;
  }
}

stream-web-exam-day-10:
class IdempotentProducerSequencer {
  private partitionSequences = new Map<number, number>();
  constructor(public producerId: number, public epoch: number) {}
  nextEnvelope(partition: number, payload: string): { producerId: number; epoch: number; partition: number; sequence: number; payload: string } {
    const currentSeq = this.partitionSequences.get(partition) || 0;
    this.partitionSequences.set(partition, currentSeq + 1);
    return {
      producerId: this.producerId,
      epoch: this.epoch,
      partition,
      sequence: currentSeq,
      payload
    };
  }
}

stream-web-assign-day-10:
class TransactionalConsumerStateStore {
  private processedIds = new Set<string>();
  private balance = 0;
  private offsets: Record<number, number> = {};
  processMessage(record: { id: string; partition: number; offset: number; amount: number }): boolean {
    if (this.processedIds.has(record.id)) {
      return false;
    }
    this.processedIds.add(record.id);
    this.balance += record.amount;
    this.offsets[record.partition] = record.offset + 1;
    return true;
  }
  getBalance(): number {
    return this.balance;
  }
  getPartitionOffsets(): Record<number, number> {
    return { ...this.offsets };
  }
}

stream-web-exam-day-11:
class BoundedFlowBuffer<T> {
  private queue: T[] = [];
  private paused = false;
  constructor(public capacity: number, public highWatermarkRatio: number = 0.8, public lowWatermarkRatio: number = 0.4) {} 
  enqueue(item: T): boolean {
    if (this.queue.length >= this.capacity) return false;
    this.queue.push(item);
    if (this.queue.length >= this.capacity * this.highWatermarkRatio) {
      this.paused = true;
    }
    return true;
  }
  dequeue(): T | null {
    if (this.queue.length === 0) return null;
    const item = this.queue.shift()!;
    if (this.queue.length <= this.capacity * this.lowWatermarkRatio) {
      this.paused = false;
    }
    return item;
  }
  isPaused(): boolean {
    return this.paused;
  }
  size(): number {
    return this.queue.length;
  }
}

stream-web-assign-day-11:
class InFlightSlotController {
  private inFlight = 0;
  constructor(public maxInFlight: number) {} 
  acquire(): boolean {
    if (this.inFlight >= this.maxInFlight) return false;
    this.inFlight++;
    return true;
  }
  release(): void {
    if (this.inFlight > 0) this.inFlight--;
  }
  getInFlight(): number {
    return this.inFlight;
  }
}

stream-web-exam-day-12:
class MicroBatchAccumulator<T> {
  private currentBatch: T[] = [];
  private firstTimestamp: number | null = null;
  constructor(public maxBatchSize: number, public maxLingerMs: number) {} 
  add(item: T, timestampMs: number): { shouldFlush: boolean; batch: T[] | null } {
    if (this.currentBatch.length === 0) {
      this.firstTimestamp = timestampMs;
    }
    this.currentBatch.push(item);
    const sizeTrigger = this.currentBatch.length >= this.maxBatchSize;
    const timeTrigger = this.firstTimestamp !== null && (timestampMs - this.firstTimestamp >= this.maxLingerMs);
    if (sizeTrigger || timeTrigger) {
      const batch = this.flush();
      return { shouldFlush: true, batch };
    }
    return { shouldFlush: false, batch: null };
  }
  flush(): T[] {
    const batch = [...this.currentBatch];
    this.currentBatch = [];
    this.firstTimestamp = null;
    return batch;
  }
}

stream-web-assign-day-12:
function tuneBatchSize(currentBatchSize: number, queueDepth: number, minBatch: number = 10, maxBatch: number = 1000): number {
  let next = currentBatchSize;
  if (queueDepth > 500) {
    next = Math.ceil(currentBatchSize * 1.2);
  } else if (queueDepth < 50) {
    next = Math.floor(currentBatchSize * 0.8);
  }
  return Math.min(maxBatch, Math.max(minBatch, next));
}

stream-web-exam-day-13:
function evaluateStreamCompression(rawSizeBytes: number, compressedSizeBytes: number, durationMs: number): { ratio: number; spaceSavingsPercent: number; throughputMBps: number } {
  if (rawSizeBytes <= 0 || compressedSizeBytes <= 0 || durationMs <= 0) {
    return { ratio: 1, spaceSavingsPercent: 0, throughputMBps: 0 };
  }
  const ratio = Math.round((rawSizeBytes / compressedSizeBytes) * 100) / 100;
  const spaceSavingsPercent = Math.round((1 - compressedSizeBytes / rawSizeBytes) * 100 * 100) / 100;
  const rawMB = rawSizeBytes / (1024 * 1024);
  const sec = durationMs / 1000;
  const throughputMBps = Math.round((rawMB / sec) * 100) / 100;
  return { ratio, spaceSavingsPercent, throughputMBps };
}

stream-web-assign-day-13:
function selectCompressionCodec(criteria: { target: 'max_throughput' | 'min_bandwidth' | 'balanced'; networkCostPerGb: number }): 'lz4' | 'snappy' | 'zstd' | 'gzip' {
  if (criteria.target === 'max_throughput') return 'lz4';
  if (criteria.target === 'min_bandwidth') return 'zstd';
  return criteria.networkCostPerGb > 0.05 ? 'zstd' : 'snappy';
}

stream-web-exam-day-14:
function applyStreamLittlesLaw(arrivalRateMsgPerSec: number, avgLatencyMs: number): { inFlightMessages: number; recommendedQueueCapacity: number } {
  const inFlightMessages = Math.round(arrivalRateMsgPerSec * (avgLatencyMs / 1000) * 100) / 100;
  const recommendedQueueCapacity = Math.ceil(inFlightMessages * 2);
  return { inFlightMessages, recommendedQueueCapacity };
}

stream-web-assign-day-14:
function calculateStreamBdp(bandwidthGbps: number, roundTripTimeMs: number): { bdpBytes: number; optimalBufferKilobytes: number } {
  const bytesPerSec = (bandwidthGbps * 1e9) / 8;
  const rttSec = roundTripTimeMs / 1000;
  const bdpBytes = Math.round(bytesPerSec * rttSec);
  const optimalBufferKilobytes = Math.ceil(bdpBytes / 1024);
  return { bdpBytes, optimalBufferKilobytes };
}

stream-web-exam-day-15:
class IngestPipelineEngine {
  private queue: { id: string; payload: string }[] = [];
  private throttled = false;
  constructor(public capacity: number, public batchLimit: number) {} 
  ingest(record: { id: string; payload: string }): { accepted: boolean; queueDepth: number; throttled: boolean } {
    if (this.queue.length >= this.capacity) {
      return { accepted: false, queueDepth: this.queue.length, throttled: true };
    }
    this.queue.push(record);
    if (this.queue.length >= this.capacity * 0.75) {
      this.throttled = true;
    }
    return { accepted: true, queueDepth: this.queue.length, throttled: this.throttled };
  }
  drainBatch(): { id: string; payload: string }[] {
    const batch = this.queue.splice(0, this.batchLimit);
    if (this.queue.length < this.capacity * 0.25) {
      this.throttled = false;
    }
    return batch;
  }
  isThrottled(): boolean {
    return this.throttled;
  }
}

stream-web-assign-day-15:
function computePipelineTelemetry(totalEvents: number, durationSec: number, latenciesMs: number[]): { throughputEventsPerSec: number; p50LatencyMs: number; p95LatencyMs: number; p99LatencyMs: number } {
  const throughputEventsPerSec = durationSec > 0 ? Math.round((totalEvents / durationSec) * 100) / 100 : 0;
  if (latenciesMs.length === 0) {
    return { throughputEventsPerSec, p50LatencyMs: 0, p95LatencyMs: 0, p99LatencyMs: 0 };
  }
  const sorted = [...latenciesMs].sort((a, b) => a - b);
  const getP = (p: number) => {
    const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
    return sorted[idx];
  };
  return {
    throughputEventsPerSec,
    p50LatencyMs: getP(50),
    p95LatencyMs: getP(95),
    p99LatencyMs: getP(99)
  };
}
